<script setup lang="ts">
import { onMounted, reactive, ref, watch } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { api } from "../../../../api";
import { COUPON_STATUS_TABS } from "../../../../dicts/status-tab";
import { activeCampus, hasPerm } from "../../../../session";
import AdminPageShell from "../../../../shared/ui/AdminPageShell.vue";
import AdminPagination from "../../../../shared/ui/AdminPagination.vue";
import type { Coupon } from "../../../../types";
import { fenToYuan, yuanToFen } from "../../../../utils/money";
const rows=ref<Coupon[]>([]),loading=ref(false),saving=ref(false),open=ref(false),editing=ref<Coupon|null>(null),page=ref(1),pageSize=ref(20),total=ref(0),keyword=ref(""),status=ref("all");
const form=reactive({kind:"platform" as "platform"|"partner",trigger:"manual" as "manual"|"lottery"|"signup",name:"",remark:"",amount:5,threshold:20,totalMode:"limited",total:100,expiryMode:"forever",expiresAt:"",featuredAfterPay:false,perUserLimit:1,targetedOnly:false});
function notify(message:string,type:"success"|"error"="success"){ElMessage({message,type,showClose:true})}function asCoupon(row:unknown){return row as Coupon}
async function load(){if(!activeCampus.value){rows.value=[];total.value=0;return}loading.value=true;try{const r=await api.coupons({page:page.value,pageSize:pageSize.value,keyword:keyword.value.trim()||undefined,campusId:activeCampus.value},status.value==="all"?undefined:status.value);rows.value=r.items;total.value=r.total}catch(e){notify(e instanceof Error?e.message:"优惠券加载失败","error")}finally{loading.value=false}}
function edit(row?:Coupon){editing.value=row??null;Object.assign(form,{kind:row?.kind??"platform",trigger:row?.trigger??"manual",name:row?.name??"",remark:row?.remark??"",amount:Number(fenToYuan(row?.amount??500)),threshold:Number(fenToYuan(row?.threshold??2000)),totalMode:row?.total===null?"unlimited":"limited",total:row?.total??100,expiryMode:row?.expiresAt?"date":"forever",expiresAt:row?.expiresAt?.slice(0,10)??"",featuredAfterPay:!!row?.featuredAfterPay,perUserLimit:Number((row as Coupon&{perUserLimit?:number})?.perUserLimit??1),targetedOnly:!!(row as Coupon&{targetedOnly?:boolean})?.targetedOnly});open.value=true}
async function save(){if(!form.name.trim())return notify("请填写券名称","error");if(form.kind==="platform"&&form.amount<=0)return notify("金额券面额必须大于 0","error");if(form.totalMode==="limited"&&form.total<1)return notify("限量券总量至少为 1","error");if(form.expiryMode==="date"&&!form.expiresAt)return notify("请选择有效期","error");saving.value=true;try{const common={name:form.name.trim(),remark:form.remark.trim(),featuredAfterPay:form.featuredAfterPay,perUserLimit:Math.max(0,form.perUserLimit),targetedOnly:form.targetedOnly};if(editing.value){await api.updateCoupon(editing.value.id,{...common,...(editing.value.kind==="platform"&&!editing.value.claimed?{amount:yuanToFen(form.amount),threshold:yuanToFen(form.threshold)}:{}),total:form.totalMode==="unlimited"?null:form.total,expiresAt:form.expiryMode==="forever"?null:form.expiresAt})}else{await api.createCoupon({...common,kind:form.kind,trigger:form.trigger,amount:form.kind==="partner"?0:yuanToFen(form.amount),threshold:form.kind==="partner"?0:yuanToFen(form.threshold),...(form.totalMode==="limited"?{total:form.total}:{}),...(form.expiryMode==="date"?{expiresAt:form.expiresAt}:{})})}open.value=false;notify(editing.value?"优惠券已更新":"优惠券已创建");await load()}catch(e){notify(e instanceof Error?e.message:"保存失败","error")}finally{saving.value=false}}
async function toggle(row:Coupon){try{await api.updateCouponStatus(row.id,row.status==="active"?"paused":"active");notify(row.status==="active"?"优惠券已暂停":"优惠券已启用");await load()}catch(e){notify(e instanceof Error?e.message:"操作失败","error")}}
async function remove(row:Coupon){try{await ElMessageBox.confirm(`确认删除「${row.name}」？`,`删除优惠券`,{type:"warning"});await api.deleteCoupon(row.id);notify("优惠券已删除");await load()}catch(e){if(e!=="cancel"&&e!=="close")notify(e instanceof Error?e.message:"删除失败","error")}}
watch([page,pageSize,status,activeCampus],load);onMounted(load);
</script>
<template><AdminPageShell title="优惠券配置" eyebrow="COUPONS" description="配置当前顶部校区的优惠券预算、领取门槛与核销效果。"><template #actions><ElButton v-if="activeCampus&&hasPerm('POST /admin/coupons')" type="primary" @click="edit()">新建优惠券</ElButton></template><div v-if="!activeCampus" class="empty-hint">请先在顶部选择校区。</div><template v-else><ElTabs v-model="status"><ElTabPane v-for="tab in COUPON_STATUS_TABS" :key="tab.key" :label="tab.label" :name="tab.key"/></ElTabs><div class="toolbar"><ElInput v-model="keyword" class="search" clearable placeholder="搜索优惠券" @keyup.enter="page=1;load()"/><ElButton @click="page=1;load()">查询</ElButton></div><ElTable v-loading="loading" :data="rows" row-key="id"><ElTableColumn prop="name" label="优惠券" min-width="180"/><ElTableColumn label="类型"><template #default="{row}">{{row.kind==='platform'?'金额券':'异业券'}}</template></ElTableColumn><ElTableColumn label="面额"><template #default="{row}">{{row.kind==='platform'?`¥${fenToYuan(row.amount)}`:'权益券'}}</template></ElTableColumn><ElTableColumn label="门槛"><template #default="{row}">{{row.threshold?`¥${fenToYuan(row.threshold)}`:'无门槛'}}</template></ElTableColumn><ElTableColumn label="总量"><template #default="{row}">{{row.total??'不限量'}}</template></ElTableColumn><ElTableColumn label="剩余"><template #default="{row}">{{row.remain??'不限量'}}</template></ElTableColumn><ElTableColumn prop="claimed" label="领取"/><ElTableColumn prop="used" label="核销"/><ElTableColumn label="有效期" min-width="150"><template #default="{row}">{{row.expiresAt?.slice(0,10)||'长期'}}</template></ElTableColumn><ElTableColumn label="操作" width="220" fixed="right"><template #default="{row}"><ElButton v-if="hasPerm('PATCH /admin/coupons/:id')" link type="primary" @click="edit(asCoupon(row))">编辑</ElButton><ElButton v-if="hasPerm('PATCH /admin/coupons/:id')" link @click="toggle(asCoupon(row))">{{row.status==='active'?'暂停':'启用'}}</ElButton><ElButton v-if="!row.claimed&&hasPerm('DELETE /admin/coupons/:id')" link type="danger" @click="remove(asCoupon(row))">删除</ElButton></template></ElTableColumn></ElTable><AdminPagination v-model:page="page" v-model:page-size="pageSize" :total="total"/></template><ElDialog v-model="open" :title="editing?'编辑优惠券':'新建优惠券'" width="min(760px, calc(100vw - 32px))" align-center :close-on-click-modal="false"><ElForm label-position="top" class="grid"><ElFormItem label="券品种"><ElSelect v-model="form.kind" :disabled="!!editing"><ElOption label="金额券" value="platform"/><ElOption label="异业券" value="partner"/></ElSelect></ElFormItem><ElFormItem label="发放方式"><ElSelect v-model="form.trigger" :disabled="!!editing"><ElOption label="手动领取" value="manual"/><ElOption label="转盘抽奖" value="lottery"/><ElOption label="新人注册" value="signup"/></ElSelect></ElFormItem><ElFormItem label="券名称" class="wide"><ElInput v-model="form.name"/></ElFormItem><ElFormItem v-if="form.kind==='platform'" label="面额（元）"><ElInputNumber v-model="form.amount" :min="0.01" :precision="2" :disabled="!!editing?.claimed"/></ElFormItem><ElFormItem v-if="form.kind==='platform'" label="使用门槛（元）"><ElInputNumber v-model="form.threshold" :min="0" :precision="2" :disabled="!!editing?.claimed"/></ElFormItem><ElFormItem label="发放总量"><ElSelect v-model="form.totalMode"><ElOption label="限量" value="limited"/><ElOption label="不限量" value="unlimited"/></ElSelect></ElFormItem><ElFormItem v-if="form.totalMode==='limited'" label="总量张数"><ElInputNumber v-model="form.total" :min="1"/></ElFormItem><ElFormItem label="有效期"><ElSelect v-model="form.expiryMode"><ElOption label="长期有效" value="forever"/><ElOption label="固定日期" value="date"/></ElSelect></ElFormItem><ElFormItem v-if="form.expiryMode==='date'" label="有效期至"><ElDatePicker v-model="form.expiresAt" type="date" value-format="YYYY-MM-DD"/></ElFormItem><ElFormItem label="每人限领"><ElInputNumber v-model="form.perUserLimit" :min="0"/></ElFormItem><ElFormItem label="展示设置"><ElCheckbox v-model="form.featuredAfterPay">支付后推荐</ElCheckbox><ElCheckbox v-model="form.targetedOnly">仅定向发放</ElCheckbox></ElFormItem><ElFormItem label="优惠说明" class="wide"><ElInput v-model="form.remark" type="textarea"/></ElFormItem></ElForm><template #footer><ElButton @click="open=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="save">保存</ElButton></template></ElDialog></AdminPageShell></template>
<style scoped>.search{width:min(360px,100%)}.empty-hint{padding:48px;text-align:center;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.wide{grid-column:1/-1}.grid :deep(.el-select),.grid :deep(.el-input-number),.grid :deep(.el-date-editor){width:100%}@media(max-width:640px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
